/* eslint-disable */
/**
 * Rest-timer notifications, imported by the generated app-shell worker.
 * Kept separate from caching so the shell worker stays generated by the build.
 *
 * The page posts the rest deadline here; the worker owns the alarm, so a phone
 * that freezes the tab still gets the "rest is over" notification, and Android
 * also gets a live countdown on the lock screen while resting.
 */
(function () {
  var TAG = "forja-rest";
  var endTimer = null;
  var tickTimer = null;
  var state = null;

  function clearTimers() {
    if (endTimer) clearTimeout(endTimer);
    if (tickTimer) clearInterval(tickTimer);
    endTimer = null;
    tickTimer = null;
  }

  function closeOngoing() {
    return self.registration
      .getNotifications({ tag: TAG })
      .then(function (list) {
        list.forEach(function (n) {
          n.close();
        });
      })
      .catch(function () {});
  }

  function mmss(seconds) {
    var s = Math.max(0, Math.round(seconds));
    var m = Math.floor(s / 60);
    var r = s % 60;
    return m + ":" + (r < 10 ? "0" + r : r);
  }

  function showOngoing() {
    if (!state) return;
    var left = (state.endsAt - Date.now()) / 1000;
    if (left <= 0) return;
    self.registration
      .showNotification(state.runningTitle || "Resting", {
        body: mmss(left),
        tag: TAG,
        renotify: false,
        silent: true,
        requireInteraction: false,
        data: { url: state.url || "/sessao" },
        icon: "/icon-192.png",
        badge: "/icon-192.png",
      })
      .catch(function () {});
  }

  function showDone() {
    if (!state) return;
    var data = state;
    state = null;
    clearTimers();
    self.registration
      .showNotification(data.title || "Rest is over", {
        body: data.body || "",
        tag: TAG,
        renotify: true,
        requireInteraction: true,
        vibrate: [400, 150, 400, 150, 600],
        data: { url: data.url || "/sessao" },
        icon: "/icon-192.png",
        badge: "/icon-192.png",
      })
      .catch(function () {});
  }

  self.addEventListener("message", function (event) {
    var msg = event.data || {};
    if (msg.type === "rest-schedule") {
      clearTimers();
      state = {
        endsAt: msg.endsAt,
        title: msg.title,
        body: msg.body,
        runningTitle: msg.runningTitle,
        url: msg.url,
      };
      var ms = msg.endsAt - Date.now();
      if (ms <= 0) {
        showDone();
        return;
      }
      endTimer = setTimeout(showDone, ms);
      if (msg.ongoing) {
        showOngoing();
        tickTimer = setInterval(showOngoing, 30000);
      }
    } else if (msg.type === "rest-cancel") {
      state = null;
      clearTimers();
      event.waitUntil(closeOngoing());
    }
  });

  self.addEventListener("notificationclick", function (event) {
    if (!event.notification || event.notification.tag !== TAG) return;
    event.notification.close();
    var url = (event.notification.data && event.notification.data.url) || "/sessao";
    event.waitUntil(
      self.clients.matchAll({ type: "window", includeUncontrolled: true }).then(function (list) {
        for (var i = 0; i < list.length; i++) {
          if ("focus" in list[i]) return list[i].focus();
        }
        return self.clients.openWindow(url);
      }),
    );
  });
})();
